ssh.response:
system {
    host-name LON-CORE-01;
    root-authentication {
        encrypted-password "$6$def456";
    }
}
interfaces {
    ge-0/0/0 {
        vlan-tagging;
        unit 0 {
            vlan-id 1;
            family inet {
                address 192.168.100.1/24;
            }
        }
        unit 100 {
            vlan-id 100;
            family inet;
        }
        unit 999 {
            vlan-id 999;
            family inet;
        }
    }
    xe-1/0/1 {
        vlan-tagging;
        unit 0 {
            vlan-id 1;
            family inet {
                address 10.0.1.1/30;
            }
        }
        unit 200 {
            vlan-id 200;
            family inet;
        }
    }
}
policy-options {
    policy-statement CUSTOMER-A-export {
        term 1 {
            then {
                community add CUSTOMER-A;
                accept;
            }
        }
    }
    policy-statement CUSTOMER-A-import {
        term 1 {
            from community CUSTOMER-A;
            then accept;
        }
        term 2 {
            then reject;
        }
    }
    policy-statement INTERNET-export {
        term 1 {
            then {
                community add INTERNET;
                accept;
            }
        }
    }
    policy-statement INTERNET-import {
        term 1 {
            from community INTERNET;
            then accept;
        }
        term 2 {
            then reject;
        }
    }
    policy-statement MGMT-export {
        term 1 {
            then {
                community add MGMT;
                accept;
            }
        }
    }
    policy-statement MGMT-import {
        term 1 {
            from community MGMT;
            then accept;
        }
        term 2 {
            then reject;
        }
    }
    community CUSTOMER-A members target:65001:100;
    community INTERNET members target:65001:200;
    community MGMT members target:65001:999;
}
routing-instances {
    CUSTOMER-A {
        instance-type vrf;
        interface ge-0/0/0.100;
        route-distinguisher 65001:100;
        vrf-import CUSTOMER-A-import;
        vrf-export CUSTOMER-A-export;
        routing-options {
            router-id 10.100.0.1;
        }
    }
    INTERNET {
        instance-type vrf;
        interface xe-1/0/1.200;
        route-distinguisher 65001:200;
        vrf-import INTERNET-import;
        vrf-export INTERNET-export;
        routing-options {
            router-id 10.150.0.1;
        }
    }
    MGMT {
        instance-type vrf;
        interface ge-0/0/0.999;
        route-distinguisher 65001:999;
        vrf-import MGMT-import;
        vrf-export MGMT-export;
        routing-options {
            router-id 10.200.0.1;
        }
    }
}
